using Ameen.Erp.Application;
using Ameen.Erp.Domain;
using Ameen.Erp.Infrastructure;
using Microsoft.EntityFrameworkCore;

namespace Ameen.Erp.Tests;

// GL05-FG04 (F10-F13): the approval batch actor and audit timestamps/revision
// are generated by the server, persisted, visible only to the owner, and remain
// identical after replay. No separate reviewer/approval policy is introduced.
public static class JournalReviewAuditFieldsSqlAcceptance
{
    public static async Task Run(string connection, Guid companyId, Actor clerk,
        Actor approver, CreateJournalRequest sample)
    {
        ErpDbContext Db() => new(new DbContextOptionsBuilder<ErpDbContext>()
            .UseSqlServer(connection).Options);
        async Task<T> Call<T>(Func<TestServices, Task<T>> action)
        {
            await using var db = Db();
            return await action(new TestServices(new SqlErpStore(db),
                new SqlTransactionRunner(db, new FixedClock()), new FixedClock()));
        }

        var request = sample with { ExternalReference = "GL05-FG04-" + Guid.NewGuid().ToString("N")[..12] };
        var created = await Call(s => s.Journal.CreateJournal(companyId, clerk,
            Fixture.Key(), request, default));
        var submitted = await Call(s => s.Journal.TransitionJournal(companyId,
            created.ResourceId, clerk, Fixture.Key(), new(created.Version), "submit", default));

        var batchKey = Fixture.Key();
        var batchRequest = new ProcessJournalsRequest("approve",
            new[] { new JournalProcessingItem(created.ResourceId, submitted.Version, Fixture.Key()) },
            batchKey);
        var accepted = await Call(s => s.Journal.ProcessJournals(
            companyId, approver, batchRequest, default));
        Ensure(accepted.AllSucceeded && accepted.SucceededCount == 1 &&
            accepted.Rows.Single().Succeeded, "GL05-FG04 approval batch did not succeed");

        var durable = await Call(s => s.Journal.DurableBatch(
            companyId, approver, batchKey, default));
        Ensure(durable.Action == "approve" && durable.CreatedBy == approver.Subject &&
            durable.Revision == 2 && durable.CreatedAt != default &&
            durable.LastModifiedAt >= durable.CreatedAt &&
            durable.FinishedAt is not null && durable.FinishedAt >= durable.CreatedAt &&
            durable.Rows.SequenceEqual(accepted.Rows),
            "GL05-FG04 reviewer, created time, revision or modified time missing in API contract");

        int auditCount, receiptCount, outboxCount;
        await using (var db = Db())
        {
            var batch = await db.Set<JournalProcessingBatch>().AsNoTracking().SingleAsync(x =>
                x.CompanyId == companyId && x.BatchKey == batchKey);
            var journal = await db.Set<JournalEntry>().AsNoTracking().SingleAsync(x =>
                x.CompanyId == companyId && x.Id == created.ResourceId);
            Ensure(batch.Id == durable.BatchId && batch.ActorId == approver.Subject &&
                batch.CreatedAt == durable.CreatedAt &&
                batch.LastModifiedAt == durable.LastModifiedAt &&
                batch.Revision == durable.Revision &&
                batch.FinishedAt == durable.FinishedAt &&
                batch.ItemCount == 1 &&
                journal.State == JournalState.Approved && journal.ApprovedBy == approver.Subject &&
                await db.Set<AuditEvent>().CountAsync(x => x.CompanyId == companyId &&
                    x.ResourceId == batch.Id && x.Action == "journal.processing.batch-created") == 1 &&
                await db.Set<AuditEvent>().CountAsync(x => x.CompanyId == companyId &&
                    x.ResourceId == batch.Id && x.Action == "journal.processing.batch-item") == 1,
                "GL05-FG04 persisted SQL approval audit did not match server fields");
            auditCount = await db.Set<AuditEvent>().CountAsync(x => x.CompanyId == companyId);
            receiptCount = await db.Set<IdempotencyRecord>().CountAsync(x => x.CompanyId == companyId);
            outboxCount = await db.Set<OutboxEvent>().CountAsync(x => x.CompanyId == companyId);
        }

        var replay = await Call(s => s.Journal.ProcessJournals(
            companyId, approver, batchRequest, default));
        var durableReplay = await Call(s => s.Journal.DurableBatch(
            companyId, approver, batchKey, default));
        Ensure(replay.Rows.SequenceEqual(accepted.Rows) &&
            durableReplay.BatchId == durable.BatchId && durableReplay.Version == durable.Version &&
            durableReplay.CreatedBy == durable.CreatedBy && durableReplay.CreatedAt == durable.CreatedAt &&
            durableReplay.LastModifiedAt == durable.LastModifiedAt &&
            durableReplay.FinishedAt == durable.FinishedAt && durableReplay.Revision == durable.Revision &&
            durableReplay.Rows.SequenceEqual(durable.Rows),
            "GL05-FG04 approval replay changed review actor, revision or timestamps");
        try
        {
            await Call(s => s.Journal.DurableBatch(companyId, clerk, batchKey, default));
            throw new Exception("GL05-FG04 batch audit leaked to another actor");
        }
        catch (BusinessException ex) when (ex.Code == "processing_batch_not_found") { }

        await using (var db = Db())
        {
            Ensure(await db.Set<AuditEvent>().CountAsync(x => x.CompanyId == companyId) == auditCount &&
                await db.Set<IdempotencyRecord>().CountAsync(x => x.CompanyId == companyId) == receiptCount &&
                await db.Set<OutboxEvent>().CountAsync(x => x.CompanyId == companyId) == outboxCount &&
                await db.Set<JournalProcessingBatch>().CountAsync(x => x.CompanyId == companyId &&
                    x.BatchKey == batchKey && x.Revision == 2) == 1,
                "GL05-FG04 read/replay caused duplicate audit, receipt, outbox or revision");
        }
        Console.WriteLine("  SQL PASS GL05-FG04 approval creator, timestamp, numeric revision, replay and actor isolation");
    }

    private static void Ensure(bool valid, string message)
    {
        if (!valid) throw new Exception(message);
    }
}
